import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 4

def design(feats):
    if len(feats.ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check if any feature shows significant association with outcome
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if abs(np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])) > 0.1:
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if p_val < 0.05:
                sig_features.append((fid, abs(t_stat)))

    # If no significant features, return empty design
    if not sig_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Sort by effect size
    sig_features.sort(key=lambda x: x[1], reverse=True)

    # Check for near-duplicates using correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)
    to_remove = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                to_remove.add(feats.ids[j])

    # Filter out near-duplicates
    unique_features = [fid for fid, _ in sig_features if fid not in to_remove]

    # If we have too many features, keep top ones (max MAX_DRIVERS)
    if len(unique_features) > MAX_DRIVERS:
        unique_features = unique_features[:MAX_DRIVERS]

    # Get driver features
    drivers = tuple(unique_features)

    # For products, check for interactions between top features
    products = []
    for i, fid1 in enumerate(unique_features):
        for j, fid2 in enumerate(unique_features[i+1:], i+1):
            products.append((fid1, fid2))

    # For columns, use all features that show some association
    columns = tuple([fid for fid, _ in sig_features if fid not in to_remove])

    # Loadings based on standardized coefficients from simple regression
    loadings = {}
    if len(columns) > 0:
        model = LogisticRegression(fit_intercept=False, max_iter=1000)
        model.fit(feats.x[:, [feats.column(fid) for fid in columns]], feats.y)
        for i, fid in enumerate(columns):
            loadings[fid] = float(model.coef_[0][i])

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

